/**
 * "Updated today" — but what changed?
 *
 * The date on every card answers *when* and stops there, which raises the
 * question it does not answer. This is the answer: the last few commits that
 * touched that world, in the words they were written in.
 *
 * The data is a build artifact (`src/worlds/changes.ts`, generated by
 * `npm run stamp` from git), so opening this costs no network call, works
 * offline, and cannot be rate-limited by GitHub. It is lazy-imported because
 * every card renders a date and almost nobody opens the history.
 */
import { useEffect, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { ExternalLink, X } from "lucide-react";
import { exactLabel, sinceLabel } from "@/worlds/freshness";
import type { WorldChange } from "@/worlds/changes";

export default function WorldChanges({
  worldKey,
  name,
  accent,
  onClose,
}: {
  worldKey: string;
  name: string;
  accent: string;
  onClose: () => void;
}) {
  const [data, setData] = useState<{ changes: WorldChange[]; repo: string } | null>(null);

  useEffect(() => {
    let live = true;
    void import("@/worlds/changes").then((m) => {
      if (live) setData({ changes: m.WORLD_CHANGES[worldKey] ?? [], repo: m.REPO_URL });
    });
    return () => {
      live = false;
    };
  }, [worldKey]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  return (
    <div
      className="fixed inset-0 z-[80] grid place-items-center bg-black/70 p-4 backdrop-blur-sm"
      onClick={onClose}
    >
      <motion.div
        initial={{ opacity: 0, scale: 0.97, y: 10 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        transition={{ duration: 0.2 }}
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-label={`Recent changes to ${name}`}
        className="relative max-h-[80vh] w-full max-w-md overflow-hidden rounded-2xl border border-border/60 bg-[#070d16]/97 shadow-[0_24px_70px_rgba(0,0,0,0.7)]"
      >
        <div
          className="border-b border-border/40 px-5 py-4"
          style={{ background: `linear-gradient(135deg, ${accent}1f, transparent 70%)` }}
        >
          <p className="font-heading text-[9px] font-bold uppercase tracking-[0.28em] text-muted-foreground">
            What changed
          </p>
          <h2 className="mt-1 font-heading text-lg font-black tracking-tight" style={{ color: accent }}>
            {name}
          </h2>
        </div>

        <button
          onClick={onClose}
          aria-label="Close"
          className="absolute right-3 top-3 rounded-full p-1.5 text-foreground/50 transition-colors hover:bg-white/10 hover:text-foreground"
        >
          <X className="h-4 w-4" />
        </button>

        <div className="max-h-[52vh] overflow-y-auto">
          {data == null ? (
            <p className="px-5 py-8 text-center text-[12px] text-muted-foreground/70">Reading the log…</p>
          ) : data.changes.length === 0 ? (
            <p className="px-5 py-8 text-center text-[12px] leading-relaxed text-muted-foreground/70">
              No history recorded for this one yet. Run <code>npm run stamp</code> after
              its next commit.
            </p>
          ) : (
            <ol className="px-5 py-3">
              {data.changes.map((c, i) => (
                <li key={c.sha} className="relative py-2.5 pl-5">
                  {/* A spine down the left, so the list reads as a sequence
                      rather than a pile. The newest dot is the accent. */}
                  <span
                    className="absolute left-0 top-[1.05rem] h-1.5 w-1.5 rounded-full"
                    style={{ background: i === 0 ? accent : "hsl(var(--muted-foreground) / 0.4)" }}
                    aria-hidden
                  />
                  {i < data.changes.length - 1 && (
                    <span
                      className="absolute left-[0.17rem] top-[1.5rem] w-px bg-border/50"
                      style={{ bottom: "-0.35rem" }}
                      aria-hidden
                    />
                  )}
                  <p className="text-[12.5px] leading-snug text-foreground/90">{c.subject}</p>
                  <div className="mt-1 flex items-center gap-2">
                    <span
                      className="font-mono text-[10px] text-muted-foreground/60"
                      title={exactLabel(c.iso) ?? undefined}
                    >
                      {sinceLabel(c.iso)}
                    </span>
                    <a
                      href={`${data.repo}/commit/${c.sha}`}
                      target="_blank"
                      rel="noreferrer noopener"
                      className="flex items-center gap-1 font-mono text-[10px] text-muted-foreground/50 transition-colors hover:text-foreground"
                    >
                      {c.sha}
                      <ExternalLink className="h-2.5 w-2.5" />
                    </a>
                  </div>
                </li>
              ))}
            </ol>
          )}
        </div>

        {data && data.changes.length > 0 && (
          <a
            href={`${data.repo}/commits/main`}
            target="_blank"
            rel="noreferrer noopener"
            className="flex items-center justify-center gap-1.5 border-t border-border/40 px-5 py-3 font-heading text-[9.5px] font-bold uppercase tracking-wider text-muted-foreground transition-colors hover:text-foreground"
          >
            Every commit on GitHub
            <ExternalLink className="h-3 w-3" />
          </a>
        )}
      </motion.div>
    </div>
  );
}

/** Wrapper so callers can mount it conditionally without an AnimatePresence each. */
export function WorldChangesPortal({
  world,
  onClose,
}: {
  world: { key: string; name: string; accent: string } | null;
  onClose: () => void;
}) {
  return (
    <AnimatePresence>
      {world && (
        <WorldChanges
          key={world.key}
          worldKey={world.key}
          name={world.name}
          accent={world.accent}
          onClose={onClose}
        />
      )}
    </AnimatePresence>
  );
}
